const names=[['Narciso Rodriguez','For Her EDP',3230000,1000000,'female'],['Narciso Rodriguez','Ambrée EDP',2000000,900000,'female'],['Emporio Armani','Stronger With You Absolutely',3300000,1000000,'male'],['Burberry','Her EDP',3360000,900000,'female'],['Lancôme','La Vie Est Belle Sparkling Edition',3300000,1000000,'female'],['Lancôme','Idôle Le Grand Parfum',3000000,1000000,'female'],['Bvlgari','Aqva Pour Homme',2450000,1000000,'male'],['Initio','Musk Therapy',6500000,1200000,'unisex'],['Prada','Paradoxe EDP',3500000,1000000,'female'],['Dior','Miss Dior Eau de Parfum',3300000,1000000,'female'],['Montblanc','Explorer',1480000,800000,'male'],['Montblanc','Signature',1900000,900000,'female'],['Giorgio Armani','Sì Passione',3300000,900000,'female'],['Gucci','Guilty Eau de Toilette',3500000,900000,'male'],['Ex Nihilo','Blue Talisman',10500000,2000000,'unisex'],['Mancera','Red Tobacco',2800000,1000000,'unisex'],['Les Liquides Imaginaires','Blanche Bête',6500000,1500000,'unisex'],['Dolce & Gabbana','The One EDP',2400000,1000000,'male'],['Dolce & Gabbana','Light Blue Pour Homme',2500000,1000000,'male'],['Dolce & Gabbana',"L’Impératrice 3 EDT",1600000,900000,'female'],['Le Labo','Another 13',4650000,1100000,'unisex'],['Musk','Kashmir',2450000,1000000,'unisex'],['Jean Paul Gaultier','So Scandal',3200000,1100000,'female'],['Jean Paul Gaultier','Scandal',4650000,1100000,'female']];
const products=names.map((p,id)=>({id,brand:p[0],name:p[1],old:p[2],price:p[3],gender:p[4]}));const money=n=>n.toLocaleString('vi-VN')+'₫';const $=s=>document.querySelector(s);let filter='all',limit=8;let cart={};try{cart=JSON.parse(localStorage.getItem('tung-cart')||'{}');if(!cart||typeof cart!=='object'||Array.isArray(cart))cart={};for(const k of Object.keys(cart))if(!products[k]||!Number.isInteger(cart[k])||cart[k]<1)delete cart[k]}catch{}const gender={female:'Nữ',male:'Nam',unisex:'Unisex'};
function render(){let list=products.filter(p=>(filter==='all'||p.gender===filter)&&(p.brand+' '+p.name).toLocaleLowerCase('vi').includes($('#search').value.trim().toLocaleLowerCase('vi')));if($('#sort').value!=='default')list.sort((a,b)=>$('#sort').value==='asc'?a.price-b.price:b.price-a.price);$('#result-count').textContent=list.length+' mùi hương';$('#products').innerHTML=list.slice(0,limit).map(p=>`<article class="product"><button class="product-image" data-detail="${p.id}" aria-label="Xem ${p.brand} ${p.name}"><span class="tag">${gender[p.gender]}</span><img src="assets/product-${p.id}.jpg" alt="${p.brand} ${p.name}" loading="lazy" width="500" height="500"></button><div class="product-brand">${p.brand}</div><h3>${p.name}</h3><div class="product-meta">${gender[p.gender]} · Nước hoa</div><div class="prices"><strong>${money(p.price)}</strong><del>${money(p.old)}</del></div><button class="add" data-add="${p.id}">Thêm vào giỏ <span>＋</span></button></article>`).join('')||'<p class="empty">Chưa tìm thấy mùi hương phù hợp. Thử tên khác nhé.</p>';$('#more').hidden=list.length<=limit}
function save(){try{localStorage.setItem('tung-cart',JSON.stringify(cart))}catch{}$('#count').textContent=Object.values(cart).reduce((a,b)=>a+b,0)}let toastTimer;function add(id){cart[id]=(cart[id]||0)+1;save();$('#toast').textContent='Đã thêm vào giỏ hàng';$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2200)}function renderCart(){$('#cart-items').innerHTML=Object.entries(cart).map(([id,q])=>{let p=products[id];return `<div class="cart-row"><img src="assets/product-${id}.jpg" alt="${p.name}"><div>${p.brand}<br>${p.name}<p>${money(p.price)}</p></div><div class="qty"><button data-qty="${id}" data-delta="-1" aria-label="Giảm số lượng">−</button>${q}<button data-qty="${id}" data-delta="1" aria-label="Tăng số lượng">+</button></div></div>`}).join('')||'<p>Giỏ hàng đang trống. Khám phá bộ sưu tập để chọn mùi hương bạn thích.</p>';$('#total').textContent=money(Object.entries(cart).reduce((s,[id,q])=>s+products[id].price*q,0));$('#checkout').disabled=!Object.keys(cart).length}
document.addEventListener('click',e=>{const a=e.target.closest('[data-add]');if(a)add(+a.dataset.add);const d=e.target.closest('[data-detail]');if(d){const p=products[d.dataset.detail];$('#detail-content').innerHTML=`<img class="detail-img" src="assets/product-${p.id}.jpg" alt="${p.name}"><div class="detail-body"><div class="eyebrow">${p.brand}</div><h2>${p.name}</h2><p>${gender[p.gender]} · ${p.brand}</p><div class="prices"><strong>${money(p.price)}</strong><del>${money(p.old)}</del></div><p class="demo-note">Ảnh và giá tham khảo từ trang mẫu. Cần xác nhận dung tích, giá và tồn kho với cửa hàng trước khi mua.</p><button class="button" data-add="${p.id}">Thêm vào giỏ ＋</button></div>`;$('#detail').showModal()}const q=e.target.closest('[data-qty]');if(q){const id=q.dataset.qty;cart[id]+=+q.dataset.delta;if(cart[id]<=0)delete cart[id];save();renderCart()}if(e.target.closest('.close'))e.target.closest('dialog').close();const g=e.target.closest('[data-guide]');if(g){setFilter(g.dataset.guide);$('#collection').scrollIntoView({behavior:'smooth'})}});
function setFilter(f){filter=f;limit=8;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===f));render()}document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>setFilter(b.dataset.filter));$('#search').oninput=()=>{limit=8;render()};$('#sort').onchange=render;$('#more').onclick=()=>{limit+=8;render()};$('#cart-open').onclick=()=>{renderCart();$('#cart').showModal()};document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));$('#checkout').onclick=()=>{const lines=['TÙNG PERFUME — PHIẾU ĐẶT HÀNG THAM KHẢO','Bản demo — chưa gửi tới cửa hàng.','',...Object.entries(cart).map(([id,q])=>`${products[id].brand} ${products[id].name} × ${q}: ${money(products[id].price*q)}`),'','Tổng: '+$('#total').textContent];const url=URL.createObjectURL(new Blob(['\ufeff'+lines.join('\n')],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='tung-perfume-phieu-dat-hang.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};save();render();
